def _app_python_sources(root: Path) -> str:
    """Concatenated ``app/**/*.py``. Docs JSON stamps are not routes."""
    app = root / "app"
    if not app.is_dir():
        return ""
    parts: List[str] = []
    for path in sorted(app.rglob("*.py")):
        parts.append(_read_if(path))
    return "\n".join(parts)


